<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Viewpage/index')}">返回可视化页面</a>|					<a href="{pigcms{:U('index')}" class="on">五图广告位分组列表</a>|					<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('add')}','创建分组',680,400,true,false,false,addbtn,'add',true);">创建分组</a>				</ul>			</div>			<div class="page_tips">				可以添加一场或多场活动，然后从不同业务中选取商品展示，多场活动下仅展示符合现在时间的活动。不设置不展示。				<br/><br/>				用户页面会按排序倒序（排序越高越靠前）展示3个正常的分类数据			</div>            <table class="search_table" width="100%">                <tr>                    <td>                        <form action="{pigcms{:U('Plat_five_adver/index')}" method="get">                            <input type="hidden" name="c" value="Plat_five_adver"/>                            <input type="hidden" name="a" value="index"/>                            城市:                            <select id="city_id" name="city_id">                                <volist name="citys" id="c">                                    <option value="{pigcms{$c.area_id}" <if condition="$_GET['city_id'] eq $c['area_id']">selected="selected"</if>>{pigcms{$c.area_name}</option>                                </volist>                            </select>                            状态:                            <select id="status" name="status">                                <option value="-1" <if condition="$_GET['status'] eq -1">selected="selected"</if>>全部</option>                                <option value="1" <if condition="$_GET['status'] eq 1">selected="selected"</if>>开启</option>                                <option value="0" <if condition="$_GET['status'] eq 0">selected="selected"</if>>关闭</option>                            </select>                            <input type="submit" value="查询" class="button"/>　                        </form>                    </td>                </tr>            </table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<if condition="$system_session['level'] eq 2 || $system_session['level'] eq 0">								<col width="180" align="center"/>							</if>						</colgroup>						<thead>							<tr>								<th>编号</th>                                <if condition="C('customization.open_view_multi_city') neq 1">								<th>城市</th>                                </if>								<th>名称</th>								<th>活动列表</th>								<th>数据来源</th>								<th>状态</th>                                <if condition="C('customization.open_view_multi_city') eq 1 ">                                    <th>指定区域</th>                                </if>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($group_list)">								<volist name="group_list" id="vo">									<tr>										<td>{pigcms{$vo.pigcms_id}</td>                                        <if condition="C('customization.open_view_multi_city') neq 1">										<td>{pigcms{$vo.city_name|default='通用'}</td>                                        </if>										<td>{pigcms{$vo.name}</td>										<td><a href="{pigcms{:U('activity_list',array('group_id'=>$vo['pigcms_id']))}">广告列表</a></td>										<td><if condition="$vo['from'] eq 1">广告图<else/>商品</if></td>										<td><if condition="$vo['status'] eq 1"><font color="green">正常</font><else/><font color="red">关闭</font></if></td>                                        <if condition="C('customization.open_view_multi_city') eq 1 ">                                            <td>                                                <if condition="$vo['city_id'] eq 0">                                                    <font color="green">--</font>                                                    <else/>                                                    <a href="{pigcms{:U('Index/check_area',array('id' => $vo['pigcms_id'],'type'=>'plat_five_adver'))}">                                                        <font color="red">指定区域</font>                                                    </a>                                                </if>                                            </td>                                        </if>										<td class="textcenter"><a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('edit',array('id'=>$vo['pigcms_id']))}','编辑分组',680,420,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="pigcms_id={pigcms{$vo.pigcms_id}" url="{pigcms{:U('del')}" tip="删除活动分类，子分类也会删除！">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter red" colspan="8">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="8">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>